function isValidBST(root: TreeNode | null): boolean {
  // Проверяем, что все значения поддерева лежат строго в интервале (low, high).
  // Бесконечности безопасны: значения узлов — 32-битные целые
  const check = (node: TreeNode | null, low: number, high: number): boolean => {
    // Пустое поддерево — корректное BST
    if (node === null) return true;

    // Узел должен быть строго между границами, заданными всеми предками
    if (node.val <= low || node.val >= high) return false;

    // Слева всё меньше node.val, справа — всё больше
    return check(node.left, low, node.val) && check(node.right, node.val, high);
  };

  return check(root, -Infinity, Infinity);
}

// Время: O(n) — каждый узел проверяется один раз
// Память: O(h) — глубина рекурсии, h — высота дерева
